CH = dict(num=11, tag="History (Part 2)", theme="Resistance, alliances, Bhakti, temples and the economy, 1000–1700 CE",
 title="Resistance and Resilience (1000–1700 CE)",
 intro="Between 1000 and 1700 CE the subcontinent faced repeated invasions, yet kingdoms, communities and traditions survived. This chapter shows how resistance (opposing threats) and resilience (enduring and adapting) worked together through war, alliances, faith, temples and trade.",
 big_questions=["How did Indian rulers use resistance and alliances to safeguard their lands?", "What factors made kingdoms and communities resilient?", "How did the Bhakti tradition foster solidarity?", "How did agriculture, trade and commerce keep the economy sound?"],
 blocks=[
 ("h2", "Key Ideas: Resistance and Resilience"),
 ("note", "DEFINITION", "**Resilience** is the capacity to survive and adapt in difficult situations while preserving inherited socio-cultural and spiritual traditions. **Resistance** is actively opposing a force or threat to protect political power, territory, interests or identity, through warfare, alliances, diplomacy or negotiation."),
 ("ul", ["Resilience is the **backbone of resistance**: leadership supplies the cause, resilience supplies the strength to endure.", "The period is a story of **conflict and cooperation**, not only of invasion.", "Fertile plains fed by perennial rivers produced surplus, which also attracted invaders from the 7th century onwards."]),
 ("h2", "Resistance in the 11th–13th Centuries"),
 ("ul", ["Arab forces came by sea and land from the mid-7th century and were repulsed by rulers of the Deccan, Malwa, Kashmir and Rajasthan.", "**1001:** Mahmūd of Ghaznī attacked the Hindu Shāhi ruler Jayapāla. Hindu Shāhis, Chandellas, Solankīs and Chauhāns fought Turkish invaders.", "**1178:** Queen **Nāikī Devī** of the Chaulukya kingdom defeated Muhammad Ghūrī at **Kasahrada**, near Mount Abu.", "**1192:** Second Battle of Tarain, Ghūrī defeated Prithvīrāj Chauhān. Chauhāns, Gahaḍavālas and Senas later came under Turkic control.", "Gujarat, Malwa and Bundelkhand under the Chandellas resisted for about a hundred years. Odisha and parts of Assam were never conquered, and peninsular India stayed free of Turkic control."]),
 ("h2", "Resistance to the Delhi Sultanate (from 1206)"),
 ("ul", ["The **iqta** system assigned territories to military commanders in place of salaries; it served revenue collection but burdened peasants.", "Sultanate armies demolished local sacred sites, so resistance had both political and cultural motives.", "Resisting states: Yādavas of Devagiri, Rajput dynasties, **Kākatīyas** of Warangal (Queen **Rūdramā Devī**, 1262–1289) and Hoysālas."]),
 ("table", ["Year", "Event"], [["1298", "Alauddin Khiljī captures Anhilwara and plunders Somnath"], ["1301", "Siege of Ranthambore"], ["1303", "Siege of Chittor"], ["1307", "Malik Kāfūr's expedition against the Yādavas of Devagiri"], ["c. 1325", "Sisodiā ruler Rāṇā Hammīr takes Mewar"], ["1336", "Vijayanagara Empire established"]]),
 ("h2", "Rajputs and the Mughals (1500–1700)"),
 ("table", ["Year", "Event"], [["1526", "First Battle of Panipat: Bābur defeats Ibrāhim Lodī; Sultanate ends"], ["1527", "Battle of Khanua: Rāṇā Sāngā's Rajput confederacy loses to Bābur"], ["1567–68", "Akbar besieges Chittor; Rāṇā Udai Singh resists for over five months, then retreats to the Aravallis"], ["1576", "Battle of Haldighati: Mahārāṇā Pratāp vs Akbar"], ["1582", "Battle of Dewair: Pratāp regains control of Mewar"], ["1605–09", "Jahāngīr's advances countered by Mahārāṇā Amar Singh"]]),
 ("ul", ["After Haldighati, Pratāp used **guerrilla warfare** in the Aravalli terrain and the **Bhils** supported him. Mewar's emblem shows a Rajput and a Bhil warrior with Eklingjī.", "A treaty exempted Mewar's ruler from attending the Mughal court, because the Mughals wanted peace on routes to Surat.", "The Kachhwāhas of Amber cooperated and received **mansabs** (ranks combining military and civil duties).", "Poet Dursā Arhā praised Pratāp for never joining the Nauroz festival or standing guard at Jharokha Darshan."]),
 ("h2", "Ahoms, Vijayanagara and Nayakas"),
 ("h3", "The Ahom kingdom (1228–1826)"),
 ("ul", ["Strategy: use forests, rivers and monsoons, avoid direct confrontation, build alliances; the **Paik system** and light **bāchārī** boats helped.", "1615: clash at Samdhara. 1662: Mīr Jumlā takes Garhgaon but the imposed treaty is renounced by Jayadhvaj Singha.", "**1671: Battle of Saraighat**, Lachit Borphukan defeats the Mughal fleet; the Brahmaputra becomes a boundary."]),
 ("h3", "Vijayanagara (from 1336)"),
 ("ul", ["Founded by **Harihara and Bukkā** near Hampi to check Sultanate expansion; river and rocky hills gave natural defence.", "1342, Battle of Kannanur: Hoysāla king Vīra Ballāla III killed. **Kumāra Kampana** later ended the Madurai Sultanate and restored images at Kanchipuram and Srirangam.", "Kṛiṣhṇadevarāya (died 1529) was its peak; **1565 Battle of Talikota** led to defeat and fragmentation into Nāyaka kingdoms.", "**Muthu Vīrappa Nāyak III** of Madurai defied the Mughal ritual of receiving the royal slipper."]),
 ("h2", "Marathas, Sikhs and Jats"),
 ("table", ["Group", "Key facts"], [["Marathas", "Śhivājī, Pratapgarh 1659 (Afzal Khan killed), coronation 1674; **swarājya** (self-rule); forts Raigad, Sinhagad as guerrilla bases; Aurangzeb spent over two decades in the Deccan"], ["Sikhs", "Guru Nānak (one God, equality); Guru Arjan Dev executed under Jahāngīr; Guru Hargobind built the **Akāl Takht** (mīrī-pīrī); Guru Tegh Bahādur executed 1675; **Khalsa 1699**; armed **misals**"], ["Jats", "Heavily taxed peasants of the Doab; revolted 1669 under Gokul Jat and 1686 under zamindars of Sinsani and Sogar; Mughals prevailed by 1691 but resistance continued"]]),
 ("note", "NOTE", "Gingee (Senji) fort in Tamil Nadu was held by Nayakas, Bijapur, Mughals, Marathas, French and English, and was declared a UNESCO World Heritage Site in 2025."),
 ("h2", "Bhakti and Sufism"),
 ("ul", ["**Bhakti** is personal devotion expressed in local languages; it stressed inclusivity and equality. Nayanars (Śhiva) and Alvars (Viṣhṇu) spread it in the south; Rāmānanda linked south and north.", "Two streams: **Nirguṇa** (formless divine, e.g. Kabīr) and **Saguṇa** (divine with attributes, e.g. Tulsīdās).", "**Nām kīrtan, satsang and sankīrtan** made worship independent of buildings; Chaitanya Mahāprabhu led sankīrtan against a Qazi's restriction.", "Local-language works: Eknāth (Marathi), Sankardev's Kīrtana Ghosha, Tulsīdās's Rāmcharitmānas (Awadhi), Atukuri Molla's Telugu Rāmāyaṇa.", "Women saints: Akkā Mahādevi, Lāl Ded, Bahinābāi. Raskhān and Rahīm wrote devotional poetry in Braj.", "**Sulh-i-kul** (‘peace with all’) became Akbar's later policy.", "**Sufism** grew in silsilahs; Chishti and Suhrawardi orders under the Sultanate, Qaddiriyya and Naqshbandiya under the Mughals; khanqahs were community centres."]),
 ("h2", "Temples and the Economy"),
 ("ul", ["Temples were economic hubs: land grants, employment for artisans and priests, credit to farmers and merchants, and centres of art and education.", "Rulers drew legitimacy from deities: Gajapatis as **Rauta of Jagannath**, Kachhwāhas for Govindadevajī, Kota rulers for Rāma.", "From the 11th century many temples were destroyed, yet rulers, guilds and communities restored them; Kashi Vishwanath was rebuilt by Toḍar Mal and Man Singh and the present temple built by Ahilyābāī Holkar in 1780.", "From the 16th century **havelī temples**, plain and in lanes, avoided destruction; Jagat Shiromani Temple, Amer, is an example.", "Land revenue was the main income, at times up to 50 per cent of produce under Alauddin Khiljī and Muhammad bin Tughlaq.", "Rope pulleys and the Persian wheel raised output; Vijayanagara invested in small-scale irrigation.", "**Hunḍī** (a bill of exchange) worked through sarrāfs and gumasthas; banjārās and caravans connected villages, towns and Central Asia; Gujarati, Malabar, Coromandel and Bengal merchants thrived in Indian Ocean trade."]),
 ("note", "IMPORTANT", "Economic strength supplied the resources for resistance: farming, irrigation, markets, merchant networks, hunḍī and Indian Ocean trade kept society stable through political change."),
 ("h2", "Quick Revision: Likely Exam Questions"),
 ("qa", [
  ("How are resistance and resilience linked?", "Resistance opposes threats; resilience provides the endurance that sustains it."),
  ("Who defeated Muhammad Ghūrī in 1178?", "Queen Nāikī Devī of the Chaulukyas at Kasahrada."),
  ("Why was the Battle of Khanua important?", "Bābur defeated Rāṇā Sāngā's Rajput confederacy in 1527, a turning point for Mughal rule."),
  ("How did Pratāp resist Akbar?", "Guerrilla warfare in the Aravallis, with Bhil support, regaining most of Mewar by the 1580s."),
  ("What was the importance of Saraighat (1671)?", "Lachit Borphukan's naval win secured the Brahmaputra as Ahom boundary."),
  ("What is mīrī-pīrī?", "The Guru's authority over worldly (mīrī) and spiritual (pīrī) matters; Akāl Takht and Harmandir Sahib."),
  ("How did Bhakti show resilience?", "Local languages, nām kīrtan and satsang let devotion continue without temples."),
  ("What is a havelī temple?", "A plain, house-like temple built in lanes to avoid destruction."),
  ("What was hunḍī?", "A bill of exchange for safe long-distance payment."),
 ]),
 ],
 takeaways=["Resistance (opposing threats) and resilience (enduring and adapting) worked together between 1000 and 1700 CE.", "Rajputs, Ahoms, Vijayanagara, Marathas, Sikhs and Jats defended lands using war, alliances, terrain and diplomacy.", "Key dates: 1001, 1178 Kasahrada, 1206 Sultanate, 1336 Vijayanagara, 1526 Panipat, 1527 Khanua, 1576 Haldighati, 1671 Saraighat, 1674 Śhivājī, 1699 Khalsa.", "Bhakti used local languages and community singing; Sufism and Sulh-i-kul added to cultural coexistence.", "Temples were economic and political centres; havelī temples show adaptation.", "A dynamic economy of agriculture, irrigation, merchants, hunḍī and Indian Ocean trade strengthened resilience."])
